    "shortDescription": "Бронзовый радиатор с кошкой на подоконнике на стене проходной Самарской ГРЭС, открыт к 150-летию отопительной батареи.",
    "fullHistory": "Бронзовая композиция появилась 9 октября 2005 года на стене проходной Самарской ГРЭС на Волжском проспекте — к 150-летию изобретения отопительной батареи. Идея принадлежала энергетикам станции, а конкурс на лучший проект выиграл самарский скульптор Николай Куклев.\n\nПамятник — это двухметровая батарея весом около 200 килограммов с подоконником, на котором устроилась кошка. Прообразом радиатора послужили старинные радиаторы из здания Самарского художественного музея: им более 90 лет, они выше современных и украшены орнаментом в стиле модерн.\n\nПервоначально кошку предлагали посадить прямо на батарею, но вариант отклонили: энергетики пояснили, что исправные батареи в городе разогреваются так сильно, что кошка такой жары не выдержала бы, — поэтому в финальной композиции она греется на подоконнике над горячим радиатором. Образ кошки скульптор создал по одной из фотографий домашних питомцев, присланных самарцами.",
