      "Бронза, высота около 2 м, вес около 200 кг, висит на стене проходной ГРЭС (Волжский проспект, 8)",
      "Прообраз радиатора — старинные радиаторы Самарского художественного музея старше 90 лет",
      "Кошка на подоконнике, а не на батарее: по словам энергетиков, исправная батарея слишком горяча"
