    "id": 19,
    "slug": "pamyatnik-klaviature",
    "title": "Памятник клавиатуре",
    "city": "Екатеринбург",
    "region": "Свердловская область",
    "year": 2005,
    "category": "Необычные",
    "shortDescription": "Бетонная клавиатура в масштабе 30:1 на набережной Исети (16×4 м, 104 клавиши) работы Анатолия Вяткина — первый в мире памятник клавиатуре.",
    "fullHistory": "Первая в Екатеринбурге ленд-арт-скульптура появилась 5 октября 2005 года на втором ярусе набережной реки Исети у улицы Гоголя. Автор идеи — художник Анатолий Вяткин; проект создан как спецпроект фестиваля «Длинные истории Екатеринбурга» (кураторы Наиля Аллахвердиева и Арсений Сергеев).\n\nЭто бетонная компьютерная клавиатура в масштабе 30:1: 16 на 4 метра, 104 клавиши весом от 100 до 500 килограммов каждая, раскладка ЙЦУКЕН/QWERTY. По словам Вяткина, исходная идея была ироничной — «клавиатура — это кладбище идей», но по предложению продюсеров концепцию изменили и сделали постоянный объект из бетона.\n\nПамятник стал культовым: в 2011 году неизвестные похитили клавиши F1, F2, F3 и Y (их позже восстановили активисты), на клавишу End в 2016 году установили мемориальную доску в честь Евгения Зорина, регулярно проводятся «субботники на клавиатуре» с шуточными чемпионатами по метанию компьютерных мышей. По статистике «Яндекса» в 2019 году памятник занимал второе место по поисковым запросам среди памятников России после Медного всадника. В сентябре 2025 года скульптуру демонтировали и отправили на реставрацию.",
    "coordinates": {
      "lat": 56.8323,
      "lng": 60.6076
    },
    "facts": [
      "Открыт 5 октября 2005 года, автор — художник Анатолий Вяткин",
      "Масштаб 30:1: 16×4 м, 104 бетонные клавиши весом от 100 до 500 кг",
      "Первая в Екатеринбурге ленд-арт-скульптура и первый в мире памятник клавиатуре",
      "В 2011 году неизвестные украли клавиши F1–F3 и Y, их восстановили горожане",
      "В сентябре 2025 года памятник сняли для реставрации"
    ],
