    "id": 35,
    "slug": "pamyatnik-mytischinskomu-vodoprovodu",
    "title": "Памятник Мытищинскому водопроводу",
    "city": "Мытищи",
    "region": "Московская область",
    "year": 2004,
    "category": "Необычные",
    "shortDescription": "Три 18-метровые трубы с задвижками у перекрёстка Мира—Юбилейная: памятник 200-летию первого российского водопровода (2004).",
    "fullHistory": "Памятник открыт 3 сентября 2004 года к 200-летию Мытищинского водопровода — первого централизованного водопровода России, построенного по указу Екатерины II и с 1804 года снабжавшего водой Москву. Автор — архитектор П. В. Глушенков.\n\nКомпозиция высотой 18 метров — три металлические трубы с водопроводными задвижками, так называемый «букет из задвижек», символизирующий струи воды. Памятник стоял на круговом движении на пересечении улиц Мира и Юбилейной, на въезде в Мытищи со стороны Волковского шоссе. Вокруг был насыпан холм диаметром 60 метров, а со стороны улицы Мира установлены необработанные гранитные слябы — символ «разверзшейся земли» в память о Громовом ключе, из которого вода поступала в водопровод.\n\nВ ночь на 10 октября 2024 года памятник сняли с фундамента: перекрёсток реконструируют, к тому же монумент находился в аварийном состоянии и подтапливал дорогу. Администрация города заявляла о планах восстановить памятник.",
    "coordinates": {
      "lat": 55.917,
      "lng": 37.725
    },
    "facts": [
      "Открыт 3 сентября 2004 года к 200-летию первого в России централизованного водопровода",
      "Архитектор — П. В. Глушенков",
      "Три металлические трубы с задвижками, высота композиции 18 м",
      "Стоял на круге улиц Мира и Юбилейная, холм диаметром 60 м",
      "В октябре 2024 года демонтирован из-за реконструкции перекрёстка с обещанием восстановления"
    ],
