    "id": 51,
    "slug": "pamyatnik-kartoshke",
    "title": "Памятник картошке",
    "city": "Мариинск",
    "region": "Кемеровская область",
    "year": 2008,
    "category": "Гастрономические",
    "shortDescription": "Деревянный клубень-мужичок в ушанке и с лопатой на берёзовых поленьях — памятник рекорду урожайности 1942 года (2008).",
    "fullHistory": "В феврале 2008 года администрация Мариинского района объявила конкурс на лучший эскиз памятника картошке. На конкурс прислали более 50 работ из пластилина, гипса и даже настоящего картофеля; участвовали школьники, пенсионеры и организации, приходили эскизы из Рязани, Тяжина и Томска. Победил проект мариинского берестянщика Юрия Михайлова.\n\nПамятник изображает лубочный клубень-мужичок с усами и хитрой улыбкой: шапка-ушанка надета набекрень, за плечо залихватски закинута лопата, стоит он на берёзовых поленьях. Торжественное открытие прошло в сентябре 2008 года, который ООН объявила Международным годом картофеля.\n\nПамятник напоминает о рекорде военных лет: в 1942 году звено А. К. Юткиной из совхоза «Красный Перекоп» собрало 1331 центнер картофеля с гектара, побив довоенный американский рекорд (1100 центнеров). История картофеля и этого рекорда изложена на деревянной стеле рядом со скульптурой на улице Ленина.",
    "coordinates": {
      "lat": 56.2147,
      "lng": 87.7472
    },
    "facts": [
      "Идея родилась из конкурса февраля 2008 года — прислали более 50 эскизов, в том числе из настоящего картофеля",
      "Автор — мариинский берестянщик Юрий Михайлов",
      "Открыт в сентябре 2008 года, объявленного ООН Международным годом картофеля",
      "Посвящён рекорду 1942 года: звено А. К. Юткиной совхоза «Красный Перекоп» собрало 1331 ц картофеля с гектара",
      "Деревянная фигура стоит на улице Ленина на берёзовых поленьях, рядом — стела с историей рекорда"
    ],
    "likes": 37,
