    "fullHistory": "Во дворе дома 12/57 по улице Фёдоровский Ручей в Великом Новгороде стоит скульптурная композиция «Капуста» — три кованых кочана. Их изготовил в 2011 году новгородский мастер-кузнец Василий Исаков; меценатом и автором идеи выступил местный предприниматель Николай Сумароков.\n\nГлавная деталь композиции — между капустными листьями можно разглядеть изображения денежных купюр: рублей, долларов и евро. Отсюда неофициальное название «денежная капуста» — ирония над «капустой» как разговорным обозначением денег.\n\nДвор дома постепенно превратился в коллекцию малых скульптур: в 2018 году рядом появилась «Золотая рыбка», есть и «Испуганный рыбак» в лодке. В 2016 году памятник капусте попадал в рейтинги самых шуточных скульптур России.",
    "coordinates": {
      "lat": 58.5216,
      "lng": 31.2756
    },
    "facts": [
      "Создана в 2011 году (не в 2010), стоит во дворе дома 12/57 по улице Фёдоровский Ручей",
      "Автор — новгородский кузнец Василий Исаков, меценат — Николай Сумароков",
      "Три кованых металлических кочана с изображениями рублей, долларов и евро между листьями",
      "Неофициальное название — «денежная капуста»",
      "Рядом во дворе — скульптуры «Золотая рыбка» (2018) и «Испуганный рыбак»"
    ],
    "likes": 13,
    "images": [],
