    "id": 67,
    "slug": "pamyatnik-kolyushke",
    "title": "Памятник блокадной колюшке",
    "city": "Кронштадт",
    "region": "Ленинградская область",
    "year": 2005,
    "category": "Гастрономические",
    "shortDescription": "Три бронзовые рыбки на волнах у Синего моста — благодарность колюшке, спасшей Кронштадт от голода в блокаду (скульптор Чепурной).",
    "fullHistory": "Памятник открыт 8 мая 2005 года у Синего моста через Обводный канал в Кронштадте: три бронзовые рыбки на металлических волнах укреплены в гранитном парапете напротив павильона мареографа Кронштадтского футштока. Скульптор — Н. В. Чепурной; памятник создан по инициативе Совета ветеранов Кронштадта и фонда «300 лет Кронштадту — возрождение святынь».\n\nВ блокаду Ленинграда, когда почти вся рыба в Финском заливе и каналах была выловлена, уцелела колюшка — мелкая «сорная» рыбка длиной 5–6 см с костными пластинками вместо чешуи, которую раньше в пищу не брали. Её ловили сачками, сумками и даже майками: за несколько часов бригады налавливали по 4–6 кг. Из колюшки варили уху и делали котлеты, а во 2-м Ленинградском медицинском институте из неё создали препарат «Жир колюшки» для лечения ожогов и ран в госпиталях.\n\nИдея памятника возникла ещё в 1957 году, толчком к её воплощению стало стихотворение Льва Ведяйкина о дне кронштадтского блокадника. На мемориальной доске — строки поэтессы Марии Аминовой: «Блокадной маленькой рыбёшке, что людям выжить помогла…». 27 января, в День полного освобождения Ленинграда от блокады, к памятнику приносят цветы; у местных рыбаков есть примета навещать его перед рыбалкой — на удачный клёв.",
    "coordinates": {
      "lat": 59.9893,
      "lng": 29.7621
    },
    "facts": [
      "Открыт 8 мая 2005 года у Синего моста на Обводном канале Кронштадта",
      "Скульптор — Н. В. Чепурной",
      "Три бронзовые рыбки на волнах — «золотые рыбки» высотой в десятки сантиметров",
      "В блокаду из колюшки делали фарш, котлеты и препарат «Жир колюшки» для госпиталей",
      "27 января, в День снятия блокады, у памятника проходят памятные мероприятия"
    ],
