    "year": 2005,
    "category": "Гастрономические",
    "shortDescription": "Металлическая композиция с плодами и ветвями лимона в сквере на Базарной площади — дань столетней традиции павловских комнатных лимонов.",
    "fullHistory": "Памятник павловскому лимону открыт летом 2005 года, в День города Павлово, в сквере на Базарной площади недалеко от набережной Оки. Композиция отлита и выкована из металла: плоды и ветви лимона, ажурные детали отсылают к знаменитому местному металлообрабатывающему ремеслу — павловской художественной ковке и литью.\n\nПоводом для установки стала более чем столетняя городская традиция: павловские жители выращивают комнатные лимоны в домах, передавая растения черенками из поколения в поколение. «Павловский лимон» — низкорослая приспособленная к комнатным условиям культура, ставшая визитной карточкой города на Оке.\n\nСкульптура считается одним из главных малых символов Павлова и входит во все туристические маршруты по городу вместе с купеческой застройкой центра и историческим музеем.",
    "coordinates": {
      "lat": 55.968,
      "lng": 43.06
    },
    "facts": [
      "Открыт летом 2005 года в День города Павлово (в исходных данных ошибочно 2012)",
      "Стоит в сквере на Базарной площади, недалеко от набережной Оки",
      "Материал — металл: кованые плоды и ветви лимона",
      "Ажурные элементы — отсылка к павловской традиции художественной обработки металла",
      "Павловские комнатные лимоны горожане выращивают более ста лет"
    ],
