    "fullHistory": "Памятник Юрию Гагарину в Брянске был открыт 12 апреля 2014 года, его установка была приурочена к 80-летию со дня рождения Ю. А. Гагарина. Памятник установлен на бульваре, носящем имя Гагарина. О намерении установить памятник Гагарину в Брянске было объявлено годом ранее, в апреле 2013 года, а 17 сентября того же года была заложена капсула в основание будущего памятника. Капсула была заложена космонавтом Алексеем Леоновым, который во время своего космического полёта стал первым в мире человеком, вышедшим в открытый космос. Также на церемонии закладки памятника присутствовали космонавты Сергей Крикалёв и Виктор Афанасьев. Автором памятника стал скульптор Равиль Юсупов.",
