    "fullHistory": "Памятник Юрию Гагарину на его родине в городе Гагарин (ранее Гжатск) был установлен в 1974 году, через шесть лет после гибели Юрия Гагарина. Открытие памятника состоялось 30 августа. В 2010 году была проведена масштабная реставрация памятника. Памятник был поставлен на Красной площади города Гагарина, напротив гостиницы «Восток». Над созданием памятника работали скульпторы Ю. Г. Орехов и М. А. Шмаков. Архитекторами монумента выступили В. А. Петербуржцев и А. В. Степанов. Фактически Юрий Гагарин родился в селе недалеко от Гжатска, но позднее его семья жила именно здесь, сюда он приезжал к родителям, в том числе и уже после совершения полёта в космос.",
