    "category": "Исторические",
    "shortDescription": "Памятник труженикам тыла (официальное название «Труженикам тыла за доблестный труд в Великой Отечественной войне») — памятник в городе Дубна Московской области.",
    "fullHistory": "Памятник труженикам тыла (официальное название «Труженикам тыла за доблестный труд в Великой Отечественной войне») — памятник в городе Дубна Московской области. Был установлен 8 мая 2015 года в городском парке Авиастроителей (парк им. С. И. Белиловского). Автор — дубненский скульптор Анатолий Шитов. Новый памятник органично вписался в существовавший мемориальный комплекс: памятник землякам, ушедшим на войну, а также гранитную плиту с именами погибших.",
