    "shortDescription": "Памятник пионерам-героям (Памятник учащимся и учителям школы № 3) — памятник пионерам Великой Отечественной войны в городе Лысьва Пермского края.",
    "fullHistory": "Памятник пионерам-героям (Памятник учащимся и учителям школы № 3) — памятник пионерам Великой Отечественной войны в городе Лысьва Пермского края. Этот памятник посвящён учащимся и учителям лысьвенской школы № 3, погибшим на фронтах войны. На вечере встречи «20 лет спустя» те, кто в 1941 году учился в школе, решили увековечить память своих учеников и учителей, оставшихся на полях сражений Великой Отечественной войны. Был объявлен сбор средств. С подписными листами в городе обошли более трехсот квартир выпускников. Старейшая учительница школы Е. И. Самойловова отправила больше 600 писем выпускникам по все стране. Необходимые деньги были собраны.",
