    "shortDescription": "Памятник Юрию Гагарину в Люберцах установлен рядом с училищем, в котором Юрий Гагарин обучался профессии литейщика. Ремесленное училище в Люберцах Гагарин окончил с отличием, получив красный диплом в 1951 году.",
    "fullHistory": "Памятник Юрию Гагарину в Люберцах установлен рядом с училищем, в котором Юрий Гагарин обучался профессии литейщика. Ремесленное училище в Люберцах Гагарин окончил с отличием, получив красный диплом в 1951 году. Памятник был установлен в 1986 году, к двадцатипятилетнему юбилею полёта Юрия Гагарина в космос. Автором памятника является скульптор Анатолий Новиков. Около монумента в памятные даты проводятся торжественные митинги с участием работников люберецкого НПП «Звезда», на котором был выпущен скафандр, в котором летал в космос Юрий Гагарин. Также на этих мероприятиях присутствуют представители администрации города, приезжают космонавты.",
