    "shortDescription": "Памятник партизанам Великой Отечественной войны — монумент в Осташкове, Тверская область. Памятник искусства федерального значения. Установлен 31 августа 1958 года. Расположен в парке Свободы, на улице Володарского.",
    "fullHistory": "Памятник партизанам Великой Отечественной войны — монумент в Осташкове, Тверская область. Памятник искусства федерального значения. Установлен 31 августа 1958 года. Расположен в парке Свободы, на улице Володарского. Монумент поставлен в память о мужестве и героизме партизан, действовавших на территории Тверской области в период Великой Отечественной войны. Бронзовые скульптуры стоят на постаменте, который облицован серым гранитом. Бронзовая скульптурная группа состоит из трёх скульптур — два партизана и женщина-партизанка. Центральная фигура партизана с поднятым автоматом олицетворяет образ командира, ведущего бойцов в бой.",
