    "fullHistory": "Памятник Денису Давыдову — памятник российскому военачальнику и поэту, герою Отечественной войны 1812 года Денису Давыдову работы скульптора Владимира Курдова в Пензе. Один из пяти памятников (бюстов) Д. В. Давыдову в Российской Федерации. Единственный памятник, увековечивший Давыдова в гражданской одежде, а не в военной форме. Памятник открыт 19 мая 1984 года в честь 200-летия со дня рождения Дениса Давыдова. Является объектом культурного наследия регионального значения (1988). Инициатор создания памятника — Георг Мясников, второй секретарь Пензенского обкома КПСС в 1961—1964 и 1965—1986 гг.",
