    "fullHistory": "Памятник Пугачёву — скульптурный монумент, посвящённый Емельяну Пугачёву — одному из предводителей крестьянского восстания XVIII века. Расположен в городе Саранск на улице Волгоградская в историческом районе города — Посоп. В 1974 году, к 200-летию народного восстания, был возведён стилизованный форт в городе Саранск, где Пугачев освободил крепостных, раздал своим войскам реквизированные богатства, и обдумывал план дальнейших действий. В 1985 году памятная композиция была дополнена монументом Емельяна Пугачёва, выполненной из белой гранитной плиты. Автором памятника является скульптор и живописец Обухов Николай Михайлович.",
