    "shortDescription": "Памятник героям-стратонавтам Павлу Федосеенко, Андрею Васенко и Илье Усыскину установлен в городе Саранск на площади перед железнодорожным вокзалом 30 января 1963 года.",
    "fullHistory": "Памятник героям-стратонавтам Павлу Федосеенко, Андрею Васенко и Илье Усыскину установлен в городе Саранск на площади перед железнодорожным вокзалом 30 января 1963 года. В январе 1934 года Павел Федосеенко, Андрей Васенко и Илья Усыскин поднялись на стратостате «Осоавиахим-1» на высоту 22 км. Стратостат был разработан одним из участников полёта — А. Васенко. При спуске стратостата произошла авария, он рухнул неподалёку от деревни Потиж-Острог на юге Мордовии, и участники полёта погибли. Первоначально памятник планировалось установить на месте падения стратостата, затем было решено установить его в столице Мордовии — Саранске.",
