    "fullHistory": "Памятник труженикам тыла — памятник в городе Славянск-на-Кубани Краснодарского края. Монумент появился по просьбам жителей города. Строительство памятника в центре Славянска-на-Кубани началось в феврале 2009 года в сквере Памяти. Работы велись на благотворительные средства, перечисленные предприятиями, общественными объединениями и жителями района. Открытие памятника было приурочено ко Дню Победы и состоялось 1 мая 2009 года. Монумент представляет собой пятиконечную звезду, установленную на монолитной плите из светло-коричневого гранита, которая, в свою очередь, находится на постаменте из тёмно-коричневого гранита.",
