    "shortDescription": "Памятная стела «Освобождение Тихвина» была установлена в память об освобождении города Тихвина от немецкой оккупации во время Великой Отечественной войны.",
    "fullHistory": "Памятная стела «Освобождение Тихвина» была установлена в память об освобождении города Тихвина от немецкой оккупации во время Великой Отечественной войны. За стойкость жителей и обеспечение возможности поставок продуктов и боеприпасов в Ленинград город Тихвин получил статус Города воинской славы. Освобождение Тихвина сыграло большую роль в прорыве блокады Ленинграда и начале наступательных операций на Ленинградском фронте. Тихвин был захвачен 8 ноября 1941 года, и это наступление немцев было большой угрозой для окружённого Ленинграда. Захват Тихвина ставил под угрозу возможность хотя бы какой-то организации снабжения блокадного города.",
