    "shortDescription": "Памятник жертвам нацизма в Красном Селе установлен в память о погибших в концлагерях взрослых и детях-узниках концлагерей.",
    "fullHistory": "Памятник жертвам нацизма в Красном Селе установлен в память о погибших в концлагерях взрослых и детях-узниках концлагерей. Этот монумент является символическим местом захоронения жителей Ленинграда и Ленинградской области, погибших за время Великой Отечественной войны в немецких концентрационных лагерях. В районе Красного Села в годы войны располагались переправочные пункты немецких концлагерей, поэтому установить такой монумент было решено именно здесь. В основании памятника помещена капсула с землёй и прахом жертв из нескольких «лагерей смерти». Памятник находится на территории центрального городского парка Красного Села, на проспекте Ленина, напротив дома номер 89.",
