    "shortDescription": "Куту́зовский фонта́н или Суук-Су (укр. Кутузовський фонтан, Сюнґю-Су, крымскотат. Süngü Suv, Сюнгю Сув) — фонтан-памятник М. И. Кутузову недалеко от места боя 24 июля 1774 года при деревне Шумы, где он был тяжело ранен п",
    "fullHistory": "Куту́зовский фонта́н или Суук-Су (укр. Кутузовський фонтан, Сюнґю-Су, крымскотат. Süngü Suv, Сюнгю Сув) — фонтан-памятник М. И. Кутузову недалеко от места боя 24 июля 1774 года при деревне Шумы, где он был тяжело ранен пулей в голову. Находится на 35-м километре трассы Симферополь-Алушта, перед поворотом на село Лучистое (Демерджи). За время существования пережил несколько реконструкций, в том числе и перенос на местности на несколько десятков метров. На Украине — памятник культурного наследия. В России — объект культурного наследия регионального значения.",
