    "shortDescription": "«Дре́во ско́рби» — памятник жертвам террористического акта, произошедшего 1—3 сентября 2004 года в здании школы № 1 в Беслане (Северная Осетия — Алания). В результате захвата террористами школы погибло 333 человека, из н",
    "fullHistory": "«Дре́во ско́рби» — памятник жертвам террористического акта, произошедшего 1—3 сентября 2004 года в здании школы № 1 в Беслане (Северная Осетия — Алания). В результате захвата террористами школы погибло 333 человека, из них 186 детей. Установлен в августе 2005 года на мемориальном кладбище города. Бронзовая композиция представляет собой ствол дерева, сформированный четырьмя женскими фигурами. Крона древа образована распростёртыми руками женщин, которые держат ангелов, символизирующих погибших детей. Высота памятника — около 9 метров. Выполнен скульпторами Аланом Корнаевым и Заурбеком Дзанаговым.",
