    "fullHistory": "Мемориал в Большом Сабске установлен в честь курсантов военных училищ, державших оборону на этом участке в период сражений на Ленинградском фронте в годы Великой Отечественной войны. Находится в деревне Большой Сабск (Волосовский район Ленинградской области), около местного Дома культуры. Мемориальный комплекс в Большом Сабске внесён в список объектов культурного наследия РФ, причем каждый из трёх входящих в него элементов включён туда по отдельности. Номер мемориала в единой Книге Памяти 02031, он был внесён в неё в январе 2011 года. Братская могила, включённая в мемориал, имеет отдельный номер в Книге Памяти — 02062. В феврале 2021 года были завершены реконструкционные работы на монументе.",
