    "shortDescription": "Металлический волк, бережно несущий телёнка, — скульптура у детской поликлиники Иванова по мотивам мультфильма «Жил-был пёс».",
    "fullHistory": "У входа в детскую поликлинику № 6 Иванова стоит волк с телёнком на руках — сцена из культового мультфильма «Жил-был пёс», где волк несёт похищенного телёнка, а тот радостно кричит «Папаня!». На постаменте так и написано: «Папаня!!!».\n\nАвтор скульптуры — ивановский мастер Владимир Волков, сотрудник «Ивтелерадио», который уже больше 17 лет делает фигуры из металлолома. Его работы рассыпаны по всему городу и собрали в парке Степанова целую галерею.\n\nВыбор места тоже часть смысла: волк с «ребёнком» на руках у входа в детскую поликлинику снимает страх перед врачами лучше всяких уговоров.",
