    "fullHistory": "В арт-сквере на улице 10 Августа, рядом с площадью Революции, лежит бронзовая такса. Скульптуру городу подарили шуйские мастера — те самые, что прославили Шую скульптурами из металлолома.\n\nУ таксы есть своя магия: уши и нос отполированы до блеска — ивановцы и туристы трут их на удачу, по аналогии со скульптурами московского метро.\n\nТакса делит сквер с другими арт-объектами — неподалёку памятник Аркадию Северному и Щудровская палатка, старейшее гражданское здание города.",
