    "fullHistory": "В Студенческом сквере Иванова, на углу улицы Арсения и Шереметевского проспекта, на лавочке сидит дедушка с клюкой, у ног — котёнок. Скульптор признался, что вложил в лицо старика черты своего прадедушки.\n\nЛавочка — не декорация: рядом можно присесть, обнять деда за плечи и сфотографироваться. Такие «сидячие» скульптуры — часть доброй традиции ивановских жанровых памятников, которых в городе больше десятка.\n\nДед стал привычной частью студенческих маршрутов — сквер живёт своей жизнью, а старик «наблюдает» за ней с той же лавочки.",
