    "fullHistory": "Аркадий Северный (настоящее имя — Аркадий Звездин) родился и вырос в Иванове, а стал легендой подпольных магнитофонных записей 1970-х — его называют родоначальником русского шансона. Официальной сцены у него не было вовсе: концерты проходили на квартирах, а слава расходилась по стране на бобинах и кассетах.\n\nПамятник открыли 18 июня 2010 года в Арт-сквере Иванова, рядом со Щудровской палаткой. Скульптор — Галим Долмагомбетов. Любопытно, что изначально монумент планировали установить в Санкт-Петербурге, где Северный жил и погиб, — но в итоге он вернулся на родину певца.\n\nСидящий на скамейке Аркадий с гитарой быстро стал любимцем горожан: к нему подсаживаются, с ним поют.",
