    "fullHistory": "В 2012 году Вологда отметила 865-летие, и студенты Вологодского института бизнеса предложили увековечить главную особенность местного говора — «оканье». Идею поддержали: на конкурс уходит около 30 эскизов учащихся художественной школы, побеждает проект архитектора Дениса Позднякова.\n\nШесть кузнецов выковали букву за две недели. Получилась трёхметровая металлическая «О» весом около 300 килограммов, «одетая» в традиционные узоры северных народов. Памятник открыли 30 июня, в День города, на Соборной горке у Кремлёвской площади — напротив дома Варлама Шаламова.\n\nРядом стоит кованая скамейка «Посидим, поокаем» с гармонью и томиком Рубцова — у вологжан целых два памятника оканью в одном сквере.",
