    "fullHistory": "У подножия Самаровского ледникового останца, где пласты горных пород хранят следы нескольких десятков тысяч лет, с 2007 года строили «Археопарк» — крупнейшую в стране реконструкцию доисторических времён под открытым небом, филиал Музея природы и человека.\n\nПервая скульптурная группа из семи мамонтов встала на подпорную насыпь в 2007-м, осенью 2008-го парк официально открылся. К 2009-му добавились «Волчья стая», «Первобытные бизоны», «Шерстистые носороги», «Пещерные медведи», пещерный лев, большерогий олень и стоянка первобытного человека. Автор всей бронзовой фауны — скульптор Андрей Ковальчук; фигуры смасштабированы от натуральной величины (носороги) до двукратного увеличения (бизоны), а рост наибольшего мамонта — 8 метров.\n\nВ 2010-м парк достроили «Бобрами» и «Табуном древних лошадей», а к XXXIX Всемирной шахматной олимпиаде смонтировали подсветку — изображение мамонтов тогда попало и на официальную эмблему олимпиады. Сегодня Археопарк — главная визитная карточка Ханты-Мансийска.",
