    "fullHistory": "В Городском саду Кургана, на виду у прогулочных аллей, с 2007 года стоит бронзовая пара: молодой отец пляшет, держась за руку с беременной женой. Жанровая композиция «Родители» появилась в городе как тихое напоминание о семейных ценностях — без пафоса, через танец и ожидание ребёнка.\n\nПара стоит прямо на газоне, без высокого постамента: к ним подходят, берутся за свободные руки и встают в общий хоровод — так скульптура и задумывалась.\n\nКомпозиция соседствует с парковой классикой — колесом обозрения и аллеями вдоль Тобола, и давно стала обязательной точкой свадебных прогулок по Кургану.",
