    "fullHistory": "В 1999 году Калмыкия отметила сразу две даты: 400-летие со дня рождения Зая-Пандиты и 350-летие созданной им письменности. К юбилеям в 5-м микрорайоне Элисты, неподалёку от «Золотой обители Будды Шакьямуни», открыли памятник — работу скульптора Р. Рокчинского.\n\nЗая-Пандита (Намкхай Гьяцо, ок. 1599–1662) — одна из ключевых фигур калмыцкой истории: религиозный деятель, просветитель и миротворец. В 1648 году он создал на основе старомонгольского письма «Тодо бичиг» — «Ясное письмо», специально приспособленное для ойратского языка. Благодаря ему у калмыков появились свои книги: буддийские каноны, летописи, юридические документы.\n\nПамятник изображает учёного в традиционных одеждах с книгой в руках — тем самым письмом, которое он подарил народу.",
