    "fullHistory": "У дороги в центре Элисты стоит седобородый старик с посохом — Цаган Аав, Белый Старец. В калмыцкой мифологии это хозяин земли, гор и воды, покровитель зверей и людей: он дарит долголетие и следит, чтобы человек брал у природы ровно столько, сколько нужно.\n\nСкульптура стала «своей» для горожан: Белого Старца, по традиции, задабривают подношениями — у подножия фигуры часто лежат монеты и ленточки. Место выбрано не случайно: степная Элиста помнит, что город вырос из калмыцкого селища, и Белый Старец здесь — хозяин, а не декорация.\n\nТочный год установки и автор фигуры в открытых источниках не названы — но координаты у неё теперь есть точнее некуда: GPS фотографа и метка OSM совпали до пятого знака.",
