    "shortDescription": "Бурятская бууза и тибетская момо из белого мрамора, каждая весом больше тонны, — блюдо-символ Бурятии на лепестках лотоса у дацана Ринпоче Багша.",
    "fullHistory": "В июле 2017 года на площадке буддийского комплекса Ринпоче Багша на Лысой горе появилась скульптурная композиция «Тибетская момо и бурятская бууза» — две огромные белоснежные буузы на цветках лотоса, выточенные из монолитного мрамора. Каждая фигура весит больше тонны, и это, по общему мнению, самая большая бууза в мире.\n\nСимволика двойная. Во-первых, бууза — главное блюдо Бурятии и измеритель достатка: «пельмень» размером с валун означает благополучие и процветание. Во-вторых, соседство момо и буузы отсылает к родству кухонь: по одной из версий, бууза пришла в Забайкалье вместе с буддизмом — как тибетские момо, только с бульоном внутри.\n\nК памятнику ходят после посещения дацана, а правильный способ поедания — надкусить сбоку, выпить бульон и доехать до постамента уже сытым.",
