    "fullHistory": "Оригинал Ждуна — скульптура Homunculus loxodontus («Гомункул слоноподобный») голландской художницы Маргрит ван Бреворт, созданная в мае 2016 года для Лейденского университета. Художница хотела поддержать пациентов, ждущих приёма у врача: безногое существо с головой морского слона, сидящее в комнате ожидания, «должно ждать своей участи с надеждой на лучшее». В Лейдене фигура мгновенно стала самой фотографируемой достопримечательностью города.\n\nВ рунете существо окрестили Ждуном — и мем пошёл в народ: бесконечное ожидание в очереди оказалось понятнее любых слов. Копии Ждуна начали расселяться по больницам и паркам мира, а летом 2017-го (фото датировано 16 июня) Ждун уже сидел на своём месте в Чите.\n\nЧитинский Ждун — в компании соседних арт-объектов у кинотеатра; приходит сидеть с ним так же, как в Лейдене: терпеливо и с надеждой.",
